function showExpeditions(){
 const list=$('#expeditions-list');list.innerHTML='';
 for(const[id,c]of Object.entries(Core.CONTRACTS)){
  const progress=state.expeditions.progress[id],row=document.createElement('article');row.className='contract-card';row.dataset.contract=id;
  const type=document.createElement('small');type.textContent=c.region+' · '+c.type;
  const title=document.createElement('h3');title.textContent=c.name;
  const description=document.createElement('p');description.textContent=c.detail;
  const status=document.createElement('p');status.className='contract-status';status.textContent=Core.contractStatus(state,id)+(progress.best===null?'':' · '+_t('game.rekord',{sec:progress.best.toFixed(1)}));
  const reward=document.createElement('span');reward.className='contract-reward';reward.textContent=c.reward[0]+' ◆ + '+c.reward[1]+' ▣';
  const action=document.createElement('button');action.id='contract-'+id;action.className='primary';action.disabled=!c.ready(state)||progress.done&&progress.claimed&&id!=='flight';
  const claim=progress.done&&!progress.claimed;action.textContent=claim?_t('game.zabrat_nagradu'):state.expeditions.active===id?_t('game.prodolzhit'):progress.done&&id==='flight'?_t('game.povtorit_marshrut'):_t('game.nachat_ekspeditsiy');
  action.onclick=()=>{if(claim){const r=Core.claimContract(state,id);$('#expeditions-feedback').textContent=r.text;if(r.ok){save();hud();showExpeditions();}return;}const r=state.expeditions.active===id?{ok:true,text:_t('game.prodolzhaem_eksped')}:Core.beginContract(state,id);if(r.ok){tracked=null;$('#expeditions').close();result(r);}else $('#expeditions-feedback').textContent=r.text;};
  row.append(type,title,description,status,reward,action);list.append(row);
 }
 $('#expeditions-wallet').textContent=wallet();if(!$('#expeditions').open)openDialog('expeditions');
}
