 for(let i=0;i<9;i++){const b=document.createElement('button');b.type='button';b.id='power-tile-'+i;b.onclick=()=>{state.powerGrid[i]=(state.powerGrid[i]+1)%4;update();};buttons.push(b);grid.append(b);}
