// v68 Star chart: draw the Cat constellation in one stroke — every line once, never twice. Stars with an odd number of lines are the ends.
let starsInput=[];
function showStars(){activePuzzle='stars';starsInput=[];$('#puzzle-feedback').textContent='';$('#puzzle-content').innerHTML='';$('#puzzle-role').textContent=_t('ch9.stars_role');$('#puzzle-title').textContent=_t('ch9.stars_title');$('#puzzle-text').textContent=_t('ch9.stars_text');
 const wrap=document.createElement('div');wrap.className='stars-puzzle';const NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('class','stars-chart');svg.setAttribute('aria-hidden','true');
 const key=(a,b)=>a<b?a+'-'+b:b+'-'+a,need=new Set(Core.LINES9.map(([a,b])=>key(a,b))),pos=i=>[8+Core.STARS9[i][0]*84,8+Core.STARS9[i][1]*84];
 const lineEls={};for(const[a,b]of Core.LINES9){const l=document.createElementNS(NS,'line'),[x1,y1]=pos(a),[x2,y2]=pos(b);l.setAttribute('x1',x1);l.setAttribute('y1',y1);l.setAttribute('x2',x2);l.setAttribute('y2',y2);l.setAttribute('class','star-line');svg.append(l);lineEls[key(a,b)]=l;}
 const chart=document.createElement('div');chart.className='stars-wrap';chart.append(svg);const count=document.createElement('p');count.className='stars-count';
 const btns=Core.STARS9.map((_,i)=>{const b=document.createElement('button');b.type='button';b.id='star-'+i;b.className='star-dot';const[x,y]=pos(i);b.style.left=x+'%';b.style.top=y+'%';b.setAttribute('aria-label',_t('ch9.star_n',{n:i+1}));b.innerHTML='<span>★</span>';chart.append(b);return b;});
 const used=()=>{const u=new Set();for(let i=1;i<starsInput.length;i++)u.add(key(starsInput[i-1],starsInput[i]));return u;};
 const update=()=>{const u=used();for(const k in lineEls)lineEls[k].classList.toggle('drawn',u.has(k));btns.forEach((b,i)=>{b.classList.toggle('on',starsInput.includes(i));b.classList.toggle('head',starsInput[starsInput.length-1]===i);});
  count.textContent=_t('ch9.stars_count',{n:u.size,m:need.size});wrap.classList.toggle('solved',u.size===need.size);$('#puzzle-feedback').textContent=u.size===need.size?_t('ch9.stars_ready'):starsInput.length?_t('ch9.stars_hint'):_t('ch9.stars_start');};
 btns.forEach((b,i)=>b.onclick=()=>{const last=starsInput[starsInput.length-1];if(last===undefined){starsInput=[i];}else{const k=key(last,i);if(last===i||!need.has(k)||used().has(k)){b.classList.remove('nope');void b.offsetWidth;b.classList.add('nope');$('#puzzle-feedback').textContent=_t('ch9.stars_no');return;}starsInput.push(i);}update();try{window.Telegram?.WebApp?.HapticFeedback?.selectionChanged();}catch{}});
 const reset=document.createElement('button');reset.type='button';reset.id='stars-reset';reset.className='secondary song-clear';reset.textContent=_t('ch7.aurora_reset');reset.onclick=()=>{starsInput=[];update();};
 wrap.append(chart,count,reset);$('#puzzle-content').append(wrap);update();openDialog('puzzle');}
// v67 Ring dial of the Gate: three rings with six positions; turning a ring also turns the next inner one. Bring every star to the top.
