 const wrap=document.createElement('div');wrap.className='aurora-puzzle';const sky=document.createElement('div');sky.className='aurora-sky';sky.innerHTML='<i></i><i></i><i></i>';const grid=document.createElement('div');grid.className='aurora-grid';
 let moves=0;const count=document.createElement('p');count.className='aurora-count';
