 for(let i=0;i<9;i++){const b=document.createElement('button');b.type='button';b.id='aurora-lamp-'+i;b.className='aurora-lamp';b.setAttribute('aria-label',_t('ch7.aurora_lamp',{n:i+1}));b.innerHTML='<span></span>';b.onclick=()=>{auroraInput=Core.auroraTap(auroraInput,i);moves++;update();try{window.Telegram?.WebApp?.HapticFeedback?.selectionChanged();}catch{}};grid.append(b);}
 const reset=document.createElement('button');reset.type='button';reset.id='aurora-reset';reset.className='secondary song-clear';reset.textContent=_t('ch7.aurora_reset');reset.onclick=()=>{auroraInput=Core.AURORA_START.slice();moves=0;update();};
