 BELLS.forEach((b,i)=>{const btn=document.createElement('button');btn.type='button';btn.id='song-bell-'+i;btn.className='song-bell';btn.dataset.bell=b;btn.innerHTML='<span></span><b></b>';btn.querySelector('b').textContent=_t('ch6.bell_'+b);btn.onclick=()=>{if(songInput.length>=3)songInput=[];songInput.push(i);btn.classList.remove('ring');void btn.offsetWidth;btn.classList.add('ring');update();};bells.append(btn);});
