 names.forEach((name,i)=>{const el=document.createElement('div');el.className='align-row forge-row';const dial=document.createElement('span');dial.className='align-dial forge-sun';const pips=[];for(let k=0;k<4;k++){const p=document.createElement('i');p.className='forge-pip';p.style.setProperty('--k',k);dial.append(p);pips.push(p);}const label=document.createElement('b');label.textContent=name;const st=document.createElement('small');const btn=document.createElement('button');btn.type='button';btn.id='forge-lens-'+i;btn.textContent=_t('ch5.lens_turn');btn.onclick=()=>{state.forgeLenses=Core.forgeTurn(state.forgeLenses,i);update();};el.append(dial,label,st,btn);list.append(el);rows.push({el,pips,state:st,btn});});
