function journalText(){return ['clueValley','clueCrater','clueResearch'].filter(id=>state.signalClues.includes(id)).map(id=>Core.SIGNAL_NOTES[id]).join('\n\n');}
function showVault(){activePuzzle='vault';$('#puzzle-feedback').textContent='';$('#puzzle-content').innerHTML='';$('#puzzle-role').textContent=_t('game.observatoriya_arhi');$('#puzzle-title').textContent=_t('game.kod_staroy');$('#puzzle-text').textContent=_t('game.vvedi_tri');const notes=document.createElement('p');notes.className='beacon-notes';notes.textContent=journalText();$('#puzzle-content').append(notes);const row=document.createElement('div');row.className='vault-code';for(let i=0;i<3;i++){const label=document.createElement('label');label.textContent=['I','II','III'][i];const input=document.createElement('input');input.type='number';input.inputMode='numeric';input.min='0';input.max='9';input.step='1';input.value='';input.setAttribute('aria-label',_t('game.tsifra_zapisi',{n:i+1}));label.append(input);row.append(label);}$('#puzzle-content').append(row);openDialog('puzzle');}
$('#next-life').onclick=()=>{$('#chapters').close();enterNextLife();};$('#journal-button').onclick=()=>{$('#signal-journal-notes').textContent=journalText()||_t('game.zapisi_esche');$('#signal-journal-blueprint').textContent=state.blueprint?_t('game.chertezh_rakety3')+' '+(state.chapter3Complete?_t('game.inzhener_poluchil'):_t('game.pereday_ego')):_t('game.chertezh_poka');$('#chapters').close();openDialog('signal-journal');};$('#journal-close').onclick=()=>$('#signal-journal').close();
$('#build').onclick=()=>{if(state.chapter<2||!state.artifact){toast(_t('game.snachala_naydi'));return;}showBuilder();};for(let b of document.querySelectorAll('[data-build]'))b.onclick=()=>{let r=Core.build(state,b.dataset.build,player);if(r.ok){const safe=renderer.safeSpawn(player.x,player.z,state);player.x=safe.x;player.z=safe.z;}result(r);$('#builder-feedback').textContent=r.text;refreshBuilder();};for(let b of document.querySelectorAll('[data-close]'))b.onclick=()=>$('#'+b.dataset.close).close();
function toggleFly(){if(window.MoonBike&&window.MoonBike.riding&&window.MoonBike.canFly&&window.MoonBike.canFly(state))return;/* v65: on a flying bike Space / the fly button lift the bike instead */if(state.engineerFixed&&!flight&&window.MoonBike&&window.MoonBike.riding){window.MoonBike.riding=false;window.MoonBike.setRide&&window.MoonBike.setRide(false);}if(!state.engineerFixed){if(player.alt<.05)player.velocity=3.7;return;}if(!flight&&player.fuel<12){toast(_t('game.podozhdi_poverhnos'));return;}flight=!flight;hud();}
$('#fly').onclick=toggleFly;$('#scan').onclick=()=>{scanUntil=time+7+Core.level(state,'scanner')*2;Core.markDaily(state,'scanner');const found=Core.scanContract(state,player,Core.scanRadius(state));save();hud();ui();toast(found?_t('game.obnaruzheno_obekto',{n:found}):_t('game.skaner_radius',{m:Math.round(Core.scanRadius(state))}));};

function pips(l){return [1,2,3].map(n=>`<i class="${n<=l?'on':''}"></i>`).join('')+`<span>${l?l+' / 3':_t('game.zakryto')}</span>`;}
function wallet(){return `◆ ${state.crystals}/${Core.capacity(state)} · ▣ ${state.metal}/${Core.capacity(state)} · ⚡ ${Math.floor(state.energy)}/${Core.energyCapacity(state)}`;}
function renderCards(){Core.syncCards(state);const count=Object.keys(state.cards).length;$('#collection-summary').textContent=`${_t('game.otkryto_6',{count:count})}`;$('#collection-wallet').textContent=wallet();if(!$('#cards-grid').children.length){for(const[id,c]of Object.entries(Core.CARDS)){const b=document.createElement('button');b.id='equipment-'+id;b.onclick=()=>showCard(id);$('#cards-grid').append(b);}}
for(const[id,c]of Object.entries(Core.CARDS)){const l=Core.level(state,id),b=$('#equipment-'+id);b.className='equipment-card'+(l?'':' locked');b.setAttribute('aria-label',c.name+', '+(l?_t('game.uroven',{n:l}):c.unlock));if(b.dataset.level===String(l))continue;b.dataset.level=String(l);b.innerHTML=`<span class="card-tag">${c.category.toUpperCase()} · ${String(c.chapter).padStart(2,'0')}</span><span class="art">${MoonCardArt(id)}</span><strong>${c.name}</strong><span class="effect">${l?Core.cardEffect(state,id):c.unlock}</span><span class="level-pips">${pips(l)}</span><span class="status">${l===3?_t('game.polnostyu_uluchshe'):l?_t('game.otkryt_uluchshenie'):_t('game.otkryvaetsya_prikl')}</span>`;}
$('#combo-status').className='combo-panel'+(Core.combo(state)?' active':'');$('#combo-status').textContent=Core.combo(state)?_t('game.komanda_razvedki'):_t('game.komanda_razvedki2');
const d=Core.daily(state);$('#daily-tasks').innerHTML=['scanner','backpack','jetpack'].map(id=>`<span class="${d.done.includes(id)?'done':''}">${d.done.includes(id)?'✓ ':'○ '}${{scanner:_t('game.skanirovanie'),backpack:_t('game.sbor_resursov'),jetpack:_t('game.polet_5')}[id]}</span>`).join('');$('#claim-daily').disabled=d.claimed||d.done.length<3;$('#claim-daily').textContent=d.claimed?_t('exp.nagrada_poluchena'):_t('game.zabrat_4');}
function refreshCard(){const id=selectedCard,c=Core.CARDS[id],l=Core.level(state,id);$('#card-art').innerHTML=MoonCardArt(id);$('#card-category').textContent=c.subtitle;$('#card-title').textContent=c.name;$('#card-level').innerHTML=pips(l);$('#card-current').textContent=l?Core.cardEffect(state,id):_t('game.kartochka_esche');$('#card-next').textContent=l&&l<3?_t('game.sleduyuschiy_urove')+' '+Core.cardEffect(state,id,l+1):l===3?_t('game.oborudovanie_uluch'):_t('game.pervyy_uroven')+' '+Core.cardEffect(state,id,1);$('#card-condition').textContent=l?wallet():_t('game.pervyy_uroven2',{task:c.unlock});let cost=l&&l<3?c.costs[l-1]:null;$('#card-upgrade').hidden=!cost;$('#card-upgrade').disabled=!cost||state.crystals<cost[0]||state.metal<cost[1];$('#card-upgrade').textContent=cost?`${_t('game.uluchshit',{v:l+1,cost:cost[0],cost2:cost[1]})}`:'';$('#card-track').textContent=_t('game.pokazat_mire');}
function showCard(id){selectedCard=id;$('#card-feedback').textContent='';refreshCard();openDialog('card-detail');}
$('#mission-toggle').onclick=()=>{const details=$('#detail'),button=$('#mission-toggle');details.hidden=!details.hidden;button.textContent=details.hidden?'+':'−';button.setAttribute('aria-expanded',String(!details.hidden));button.setAttribute('aria-label',details.hidden?_t('game.razvernut_podskazk'):_t('game.svernut_podskazku'));};
$('#collection').onclick=()=>{Core.tick(state);renderCards();openDialog('cards');};
$('#card-upgrade').onclick=()=>{const r=Core.upgrade(state,selectedCard);$('#card-feedback').textContent=r.text;if(r.ok){save();hud();renderCards();refreshCard();}};
$('#card-track').onclick=()=>{const c=Core.CARDS[selectedCard];if(c.chapter>state.chapter){$('#card-feedback').textContent=_t('game.eta_metka',{n:c.chapter});return;}let point=c.point;
if(selectedCard==='scanner'&&state.chapter>=2)point='navigator';
tracked={point,chapter:state.chapter,name:c.name};$('#card-detail').close();$('#cards').close();toast(_t('game.metka_kompase')+' '+c.name);};
$('#claim-daily').onclick=()=>{const r=Core.claimDaily(state);$('#daily-feedback').textContent=r.text;if(r.ok){save();hud();renderCards();}};
function refreshBuilder(){const names={habitat:_t('game.zhiloy_modul'),workshop:_t('core.masterskaya'),solar:_t('core.solnechnaya_stants'),beacon:_t('game.mayak_lagerya'),dock:_t('game.dok_drona')};$('#base-energy').textContent=`${_t('game.energii_chas',{energy:Math.floor(state.energy),energyCapacity:Core.energyCapacity(state),energyRate:Core.energyRate(state),crystals:state.crystals,metal:state.metal})}`;
for(const b of document.querySelectorAll('[data-build]')){let id=b.dataset.build,built=state.buildings.includes(id),[c,m]=Core.COST[id],req={solar:1,beacon:2,dock:3}[id]||0,locked=Core.level(state,'workshop')<req;b.disabled=built||locked||state.crystals<c||state.metal<m;b.innerHTML=names[id]+` <span>${built?_t('game.postroeno'):locked?_t('game.masterskaya',{n:req}):c+' ◆ + '+m+' ▣'}</span>`;}
$('#craft-crystals').disabled=Core.level(state,'workshop')<1||state.energy<3;$('#craft-metal').disabled=Core.level(state,'workshop')<2||state.energy<2;}
function showBuilder(){Core.tick(state);refreshBuilder();$('#builder-feedback').textContent='';openDialog('builder');}
